13: export function refreshWindowMetrics(size?: { windowWidth?: number; windowHeight?: number }) {
14:   let info: Partial<UniNamespace.GetWindowInfoResult> = {}
15:   try { info = uni.getWindowInfo() } catch {
16:     try { info = uni.getSystemInfoSync() } catch { /* Keep the last usable metrics. */ }
17:   }
18:   const width = nonnegative(size?.windowWidth, nonnegative(info.windowWidth, metrics.width))
19:   const height = nonnegative(size?.windowHeight, nonnegative(info.windowHeight, metrics.height))
20:   if (width > 0) metrics.width = width
21:   if (height > 0) metrics.height = height
22:   metrics.statusBarHeight = nonnegative(info.statusBarHeight, metrics.statusBarHeight)
23:   const safe = info.safeAreaInsets
24:   metrics.safeTop = nonnegative(safe?.top, Math.max(metrics.safeTop, metrics.statusBarHeight))
25:   metrics.safeBottom = nonnegative(safe?.bottom, metrics.safeBottom)
26:   metrics.safeLeft = nonnegative(safe?.left, metrics.safeLeft)
27:   metrics.safeRight = nonnegative(safe?.right, metrics.safeRight)
28: }
29: 
30: const resize = (event: UniNamespace.WindowResizeResult) => refreshWindowMetrics(event.size)
31: 
32: export function useWindowMetrics() {
33:   refreshWindowMetrics()
34:   users++
35:   if (!listening && typeof uni.onWindowResize === 'function' && typeof uni.offWindowResize === 'function') {
36:     try { uni.onWindowResize(resize); listening = true } catch { /* Page onResize remains available. */ }
37:   }
38:   // Components can use the page hook too; refreshed on return from cached pages.
39:   onShow(() => refreshWindowMetrics())
40:   onResize(event => refreshWindowMetrics(event.size))
41:   onScopeDispose(() => {
42:     users--
43:     if (users === 0 && listening) {
44:       try { uni.offWindowResize?.(resize) } catch { /* Best-effort on older runtimes. */ }
45:       listening = false
46:     }
47:   })
48:   return { metrics: readonly(metrics), refresh: refreshWindowMetrics,
49:     safeStyle: computed(() => ({ paddingLeft: `${metrics.safeLeft}px`, paddingRight: `${metrics.safeRight}px` })) }
50: }
